message.content:
{"diagnosis": "Fetch makes no progress (max_addr 0x00000000, FAIL 0xdead) because mem_valid stays low so mem_ready never returns. The excerpt resets mem_state <= 1 while clearing mem_valid <= 0, entering the wait state instead of idle 0. With mem_state stuck at 1 with mem_valid low, the state 0 branch that asserts mem_valid and moves to 1 can never run, deadlocking fetch.", "patch_diff": "diff --git a/picorv32.v b/picorv32.v
--- a/picorv32.v
+++ b/picorv32.v
@@ -565,8 +565,8 @@
 	always @(posedge clk) begin
 		if (!resetn || trap) begin
 			if (!resetn)
-				mem_state <= 1;
+				mem_state <= 0;
 			if (!resetn || mem_ready)
 				mem_valid <= 0;
 			mem_la_secondword <= 0;
 			prefetched_high_word <= 0;
", "expected": "tohost PASS (not FAIL 0xdead) with fetch progress max_addr != 0"}

